        if _is_err(ln):
            return ln
        rn = _to_number(right)
        if _is_err(rn):
            return rn
        ln = float(ln)
        rn = float(rn)
        if op == "+":
            r = ln + rn
        elif op == "-":
            r = ln - rn
        elif op == "*":
            r = ln * rn
        elif op == "/":
            if rn == 0.0:
                return "#DIV/0!"
            r = ln / rn
        elif op == "^":
            if ln == 0.0 and rn < 0:
                return "#DIV/0!"
