"""A spreadsheet formula engine (standard library only, Python 3.11)."""

from __future__ import annotations

import math
import re
from decimal import Decimal, ROUND_HALF_UP, localcontext

__all__ = ["Sheet"]

MAX_ROWS = 9999
MAX_COLS = 26 * 26  # A..ZZ

_ERROR_CODES = frozenset({
    "#DIV/0!", "#VALUE!", "#REF!", "#NAME?", "#PARSE!", "#CYCLE!",
})

_REF_RE = re.compile(r"[A-Za-z]{1,2}[0-9]{1,4}")
_IDENT_RE = re.compile(r"[A-Za-z][A-Za-z0-9_]*")
_NUM_TOKEN_RE = re.compile(r"[0-9]*\.?[0-9]+(?:[eE][+-]?[0-9]+)?")
_NUM_LIT_RE = re.compile(r"[+-]?(?:[0-9]+\.?[0-9]*|\.[0-9]+)(?:[eE][+-]?[0-9]+)?")
_CMP_RE = re.compile(r"<=|>=|<>|[=<>]")
_WS_RE = re.compile(r"[ \t\r\n]+")


def _col_to_num(letters: str) -> int:
    n = 0
    for ch in letters:
        n = n * 26 + (ord(ch) - ord("A") + 1)
    return n


def _num_to_col(n: int) -> str:
    if n <= 26:
        return chr(ord("A") + n - 1)
    n -= 1
    return _num_to_col(n // 26) + chr(ord("A") + n % 26)


def _split_ref_text(text: str) -> tuple[str, str] | None:
    """Split 'AA10' style text into (letters, digits), or None."""
    i = 0
    while i < len(text) and text[i].isalpha():
        i += 1
    if i == 0 or i == len(text):
        return None
    letters = text[:i]
    digits = text[i:]
    if not digits.isdigit():
        return None
    return (letters.upper(), digits)


def _parse_ref(ref: str) -> tuple[int, int]:
    """Parse a cell reference string -> (row, col) 1-based, or raise ValueError."""
    if not isinstance(ref, str):
        raise ValueError("invalid reference")
    parts = _split_ref_text(ref)
    if parts is None:
        raise ValueError("invalid reference")
    letters, digits = parts
    if len(letters) > 2 or len(digits) > 4:
        raise ValueError("invalid reference")
    col = _col_to_num(letters)
    row = int(digits)
    if row < 1 or row > MAX_ROWS or col < 1 or col > MAX_COLS:
        raise ValueError("invalid reference")
    return (row, col)


def _canonical_ref(ref: str) -> str:
    row, col = _parse_ref(ref)
    return _num_to_col(col) + str(row)


def _is_err(v: object) -> bool:
    return isinstance(v, str) and v in _ERROR_CODES


def _to_number(v: object):
    """Arithmetic coercion: float or error string."""
    if isinstance(v, bool):
        return 1.0 if v else 0.0
    if isinstance(v, float):
        return v
    if v is None:
        return 0.0
    return "#VALUE!"


def _to_text(v: object) -> str:
    if v is None:
        return ""
    if isinstance(v, bool):
        return "TRUE" if v else "FALSE"
    if isinstance(v, str):
        return v
    if isinstance(v, float):
        if math.isfinite(v) and v == int(v) and abs(v) < 1e15:
            return str(int(v))
        return repr(v)
    return str(v)


def _compare(a: object, b: object):
    """Returns ('num'|'text', x, y) or an error string."""
    if isinstance(a, bool):
        a = 1.0 if a else 0.0
    if isinstance(b, bool):
        b = 1.0 if b else 0.0
    if a is None:
        a = 0.0
    if b is None:
        b = 0.0
    a_num = isinstance(a, float)
    b_num = isinstance(b, float)
    if a_num and b_num:
        return ("num", a, b)
    if not a_num and not b_num:
        return ("text", str(a).lower(), str(b).lower())
    return "#VALUE!"


def _cmp_apply(kind: str, x, y, op: str) -> bool:
    if op == "=":
        return x == y
    if op == "<>":
        return x != y
    if op == "<":
        return x < y  # type: ignore[operator]
    if op == ">":
        return x > y  # type: ignore[operator]
    if op == "<=":
        return x <= y  # type: ignore[operator]
    return x >= y  # type: ignore[operator]


def _round_half_away(x: float, digits: int) -> float:
    if not math.isfinite(x):
        return x
    with localcontext() as ctx:
        ctx.prec = 80
        d = Decimal(repr(x))
        q = Decimal(1).scaleb(-digits)
        try:
            r = d.quantize(q, rounding=ROUND_HALF_UP)
        except Exception:
            r = d
        return float(r)


# ---------------------------------------------------------------------------
# AST nodes
# ---------------------------------------------------------------------------


class _Node:
    __slots__ = ()


class _Num(_Node):
    __slots__ = ("value",)

    def __init__(self, value: float) -> None:
        self.value = value


class _Str(_Node):
    __slots__ = ("value",)

    def __init__(self, value: str) -> None:
        self.value = value


class _Bool(_Node):
    __slots__ = ("value",)

    def __init__(self, value: bool) -> None:
        self.value = value


class _Ref(_Node):
    __slots__ = ("row", "col")

    def __init__(self, row: int, col: int) -> None:
        self.row = row
        self.col = col


class _Range(_Node):
    __slots__ = ("r1", "c1", "r2", "c2")

    def __init__(self, r1: int, c1: int, r2: int, c2: int) -> None:
        self.r1 = r1
        self.c1 = c1
        self.r2 = r2
        self.c2 = c2


class _Bin(_Node):
    __slots__ = ("op", "left", "right")

    def __init__(self, op: str, left: _Node, right: _Node) -> None:
        self.op = op
        self.left = left
        self.right = right


class _Un(_Node):
    __slots__ = ("op", "operand")

    def __init__(self, op: str, operand: _Node) -> None:
        self.op = op
        self.operand = operand


class _Call(_Node):
    __slots__ = ("name", "args")

    def __init__(self, name: str, args: list[_Node]) -> None:
        self.name = name
        self.args = args


class _Bad(_Node):
    """Evaluates to a fixed error (out-of-bounds ref, bare identifier, ...)."""
    __slots__ = ("err",)

    def __init__(self, err: str) -> None:
        self.err = err


class _ParseError(Exception):
    pass


# ---------------------------------------------------------------------------
# Tokenizer
# ---------------------------------------------------------------------------


def _tokenize(src: str) -> list[tuple[str, str]]:
    tokens: list[tuple[str, str]] = []
    i = 0
    n = len(src)
    while i < n:
        ch = src[i]
        if ch in " \t\r\n":
            i += 1
            continue
        if ch == '"':
            j = i + 1
            buf: list[str] = []
            while True:
                if j >= n:
                    raise _ParseError("unterminated string")
                if src[j] == '"':
                    if j + 1 < n and src[j + 1] == '"':
                        buf.append('"')
                        j += 2
                    else:
                        j += 1
                        break
                else:
                    buf.append(src[j])
                    j += 1
            tokens.append(("str", "".join(buf)))
            i = j
            continue
        if ch.isdigit() or (ch == "." and i + 1 < n and src[i + 1].isdigit()):
            m = _NUM_TOKEN_RE.match(src, i)
            if not m:
                raise _ParseError("bad number")
            tokens.append(("num", m.group(0)))
            i = m.end()
            continue
        if ch.isalpha():
            m = _IDENT_RE.match(src, i)
            tokens.append(("ident", m.group(0)))
            i = m.end()
            continue
        if ch == "(":
            tokens.append(("lparen", ch))
            i += 1
            continue
        if ch == ")":
            tokens.append(("rparen", ch))
            i += 1
            continue
        if ch == ",":
            tokens.append(("comma", ch))
            i += 1
            continue
        if ch == ":":
            tokens.append(("colon", ch))
            i += 1
            continue
        if ch in "+-*/^&":
            tokens.append(("op", ch))
            i += 1
            continue
        m = _CMP_RE.match(src, i)
        if m:
            tokens.append(("op", m.group(0)))
            i = m.end()
            continue
        raise _ParseError("unexpected character")
    return tokens


# ---------------------------------------------------------------------------
# Parser
# ---------------------------------------------------------------------------


class _Parser:
    """Precedence (low to high): cmp < concat < add < mul < unary < power < primary.

    Unary binds tighter than power on its LEFT (so -2^2 = -(2^2) = -4) but the
    exponent of ^ is parsed with unary allowed (so 2^-1 = 0.5). Power is
    right-associative: 2^3^2 = 2^(3^2) = 512.
    """

    def __init__(self, tokens: list[tuple[str, str]]) -> None:
        self.tokens = tokens
        self.pos = 0

    def _peek(self) -> tuple[str, str] | None:
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def _next(self) -> tuple[str, str]:
        tok = self._peek()
        if tok is None:
            raise _ParseError("unexpected end of formula")
        self.pos += 1
        return tok

    def _expect(self, kind: str) -> tuple[str, str]:
        tok = self._peek()
        if tok is None or tok[0] != kind:
            raise _ParseError("expected " + kind)
        self.pos += 1
        return tok

