                self._next()
                left = _Bin(tok[1], left, self.parse_concat())
            else:
                return left

    def parse_concat(self) -> _Node:
        left = self.parse_add()
        while True:
            tok = self._peek()
            if tok is not None and tok[0] == "op" and tok[1] == "&":
                self._next()
                left = _Bin("&", left, self.parse_add())
            else:
                return left

    def parse_add(self) -> _Node:
        left = self.parse_mul()
        while True:
            tok = self._peek()
            if tok is not None and tok[0] == "op" and tok[1] in ("+", "-"):
                self._next()
                left = _Bin(tok[1], left, self.parse_mul())
            else:
                return left

    def parse_mul(self) -> _Node:
        left = self.parse_unary()
        while True:
            tok = self._peek()
            if tok is not None and tok[0] == "op" and tok[1] in ("*", "/"):
                self._next()
                left = _Bin(tok[1], left, self.parse_unary())
            else:
                return left

    def parse_unary(self) -> _Node:
        tok = self._peek()
        if tok is not None and tok[0] == "op" and tok[1] in ("+", "-"):
            self._next()
            return _Un(tok[1], self.parse_unary())
        return self.parse_power()

    def parse_power(self) -> _Node:
        base = self.parse_primary()
        tok = self._peek()
        if tok is not None and tok[0] == "op" and tok[1] == "^":
            self._next()
            return _Bin("^", base, self.parse_unary())
        return base

    def parse_primary(self) -> _Node:
        tok = self._next()
        kind, text = tok
        if kind == "num":
            try:
                return _Num(float(text))
            except ValueError:
                raise _ParseError("bad number")
        if kind == "str":
            return _Str(text)
        if kind == "lparen":
            node = self.parse_cmp()
            self._expect("rparen")
            return node
        if kind == "ident":
            return self._ident_node(text)
        raise _ParseError("unexpected token")

    def _ident_node(self, text: str) -> _Node:
        nxt = self._peek()
        if nxt is not None and nxt[0] == "lparen":
            self._next()
            args: list[_Node] = []
            after = self._peek()
            if after is not None and after[0] == "rparen":
                self._next()
            else:
                while True:
                    args.append(self.parse_arg())
                    tok2 = self._next()
                    if tok2[0] == "comma":
                        continue
                    if tok2[0] == "rparen":
                        break
                    raise _ParseError("expected , or )")
            return _Call(text.upper(), args)
        up = text.upper()
        if up == "TRUE":
            return _Bool(True)
        if up == "FALSE":
            return _Bool(False)
        parts = _split_ref_text(text)
        if parts is not None and len(parts[0]) <= 2 and len(parts[1]) <= 4:
            letters, digits = parts
            row = int(digits)
            col = _col_to_num(letters)
            if 1 <= row <= MAX_ROWS and 1 <= col <= MAX_COLS:
                return self._maybe_range(row, col)
            return _Bad("#REF!")
        # Reference-shaped but out of bounds (e.g. A10000, AAA1)?
        if _looks_like_ref(text):
            return _Bad("#REF!")
        return _Bad("#NAME?")

    def _maybe_range(self, row: int, col: int) -> _Node:
        nxt = self._peek()
        if nxt is not None and nxt[0] == "colon":
            self._next()
            tok3 = self._next()
            if tok3[0] != "ident":
                raise _ParseError("bad range")
            parts = _split_ref_text(tok3[1])
            if parts is None or len(parts[0]) > 2 or len(parts[1]) > 4:
                raise _ParseError("bad range")
            r2 = int(parts[1])
            c2 = _col_to_num(parts[0])
            return _Range(row, col, r2, c2)
        return _Ref(row, col)

    def parse_arg(self) -> _Node:
        """A function argument: a range, or a full expression."""
        tok = self._peek()
        if tok is not None and tok[0] == "ident":
            parts = _split_ref_text(tok[1])
            if (
                parts is not None
                and len(parts[0]) <= 2
                and len(parts[1]) <= 4
                and self.pos + 1 < len(self.tokens)
                and self.tokens[self.pos + 1][0] == "colon"
            ):
                self._next()  # first ref
                self._next()  # colon
                tok3 = self._next()
                if tok3[0] != "ident":
                    raise _ParseError("bad range")
                parts3 = _split_ref_text(tok3[1])
                if parts3 is None or len(parts3[0]) > 2 or len(parts3[1]) > 4:
                    raise _ParseError("bad range")
                r1 = int(parts[1])
                c1 = _col_to_num(parts[0])
                r2 = int(parts3[1])
                c2 = _col_to_num(parts3[0])
                return _Range(r1, c1, r2, c2)
        return self.parse_cmp()


def _looks_like_ref(text: str) -> bool:
    """True if text is reference-shaped but out of bounds (A10000, AAA1, ZZ9999 is in bounds though)."""
    parts = _split_ref_text(text)
    if parts is None:
        return False
    letters, digits = parts
    if not letters or not digits:
        return False
    # Reference-shaped: letters then digits, digits with no leading-zero-only weirdness.
    return True


def _parse_formula(src: str) -> _Node:
    tokens = _tokenize(src)
    if not tokens:
        raise _ParseError("empty formula")
    return _Parser(tokens).parse()


# ---------------------------------------------------------------------------
# Sheet
# ---------------------------------------------------------------------------


class _Cell:
    __slots__ = ("raw", "is_formula", "value")

    def __init__(self) -> None:
        self.raw: str | None = None
        self.is_formula: bool = False
        self.value: object = None


class Sheet:
    def __init__(self) -> None:
        self._cells: dict[tuple[int, int], _Cell] = {}
        self._formulas: dict[tuple[int, int], _Node] = {}
        self._undo_stack: list[tuple[tuple[int, int], str | None]] = []
        self._deps_cache: dict[tuple[int, int], list[tuple[int, int]]] = {}

    # -- public API ---------------------------------------------------------

    def set(self, ref: str, raw: str) -> None:
        if not isinstance(raw, str):
            raise TypeError("raw must be a string")
        row, col = _parse_ref(ref)
        key = (row, col)
        cell = self._cells.get(key)
        if cell is None:
            cell = _Cell()
            self._cells[key] = cell
        old_raw = cell.raw
        self._apply_raw(key, cell, raw)
        self._undo_stack.append((key, old_raw))
        self._reevaluate()

    def get_raw(self, ref: str) -> str | None:
        row, col = _parse_ref(ref)
        cell = self._cells.get((row, col))
        if cell is None or cell.raw is None:
            return None
        return cell.raw

    def get(self, ref: str):
        row, col = _parse_ref(ref)
        cell = self._cells.get((row, col))
        if cell is None or cell.raw is None:
            return None
        if cell.is_formula:
            return cell.value
        return self._eval_literal(cell.raw)

    def undo(self) -> bool:
        if not self._undo_stack:
            return False
        key, old_raw = self._undo_stack.pop()
        cell = self._cells.get(key)
        if cell is None:
            cell = _Cell()
            self._cells[key] = cell
        self._apply_raw(key, cell, old_raw if old_raw is not None else "")
        self._reevaluate()
        return True

    def dependents(self, ref: str) -> list[str]:
        row, col = _parse_ref(ref)
        target = (row, col)
        rev: dict[tuple[int, int], set[tuple[int, int]]] = {}
        for key in self._formulas:
            for dep in self._formula_deps(key):
                rev.setdefault(dep, set()).add(key)
        seen = {target}
        frontier = [target]
        result: set[tuple[int, int]] = set()
        while frontier:
            cur = frontier.pop()
            for nxt in rev.get(cur, ()):
                if nxt not in seen:
                    seen.add(nxt)
                    result.add(nxt)
                    frontier.append(nxt)
        return [_num_to_col(c) + str(r) for (r, c) in sorted(result)]

    def to_csv(self) -> str:
        if not self._cells:
            return ""
        max_row = 0
        max_col = 0
        for (r, c), cell in self._cells.items():
            if cell.raw is not None:
                if r > max_row:
                    max_row = r
                if c > max_col:
                    max_col = c
        lines: list[str] = []
        for r in range(1, max_row + 1):
            fields: list[str] = []
            for c in range(1, max_col + 1):
                cell = self._cells.get((r, c))
                if cell is None or cell.raw is None:
                    fields.append("")
                else:
                    v = self.get(_num_to_col(c) + str(r))
                    fields.append(self._csv_field(_to_text(v)))
            lines.append(",".join(fields))
        return "\n".join(lines)

    # -- internals ----------------------------------------------------------

    @staticmethod
    def _csv_field(s: str) -> str:
        if "," in s or '"' in s or "\n" in s:
            return '"' + s.replace('"', '""') + '"'
        return s

    def _apply_raw(self, key: tuple[int, int], cell: _Cell, raw: str) -> None:
        if raw == "":
            cell.raw = None
            cell.is_formula = False
            self._formulas.pop(key, None)
            self._deps_cache.pop(key, None)
            return
        cell.raw = raw
        if raw.startswith("="):
            cell.is_formula = True
            try:
                self._formulas[key] = _parse_formula(raw[1:])
            except _ParseError:
                self._formulas[key] = _Bad("#PARSE!")
        else:
            cell.is_formula = False
            self._formulas.pop(key, None)
        self._deps_cache.pop(key, None)

    @staticmethod
    def _eval_literal(raw: str):
        text = raw.strip()
        if text == "":
            return None
        if _NUM_LIT_RE.fullmatch(text):
            try:
                return float(text)
            except ValueError:
                pass
        return raw

    def _formula_deps(self, key: tuple[int, int]) -> list[tuple[int, int]]:
        deps = self._deps_cache.get(key)
        if deps is not None:
            return deps
        ast = self._formulas.get(key)
        deps = []
        if ast is not None:
            seen: set[tuple[int, int]] = set()
            stack: list[_Node] = [ast]
            while stack:
                cur = stack.pop()
                if isinstance(cur, _Ref):
                    if cur.row < 1 or cur.row > MAX_ROWS or cur.col < 1 or cur.col > MAX_COLS:
                        continue
                    d = (cur.row, cur.col)
                    if d not in seen:
                        seen.add(d)
                        deps.append(d)
                elif isinstance(cur, _Range):
                    r1, r2 = min(cur.r1, cur.r2), max(cur.r1, cur.r2)
                    c1, c2 = min(cur.c1, cur.c2), max(cur.c1, cur.c2)
                    for r in range(r1, r2 + 1):
                        for c in range(c1, c2 + 1):
                            d = (r, c)
                            if d not in seen:
                                seen.add(d)
                                deps.append(d)
                elif isinstance(cur, _Bin):
                    stack.append(cur.left)
                    stack.append(cur.right)
                elif isinstance(cur, _Un):
                    stack.append(cur.operand)
                elif isinstance(cur, _Call):
                    stack.extend(cur.args)
        self._deps_cache[key] = deps
        return deps

    def _reevaluate(self) -> None:
        """Re-evaluate every formula cell, detecting cycles first."""
        # Phase 1: find all cells that are part of a cycle via iterative DFS.
        WHITE, GRAY, BLACK = 0, 1, 2
        color: dict[tuple[int, int], int] = {}
        cyclic: set[tuple[int, int]] = set()
        for start in self._formulas:
            if color.get(start, WHITE) != WHITE:
                continue
            # Each frame: [node, deps, index]
            frames: list[list] = [[start, self._formula_deps(start), 0]]
            color[start] = GRAY
            path: list[tuple[int, int]] = [start]
            on_path: set[tuple[int, int]] = {start}
            while frames:
                frame = frames[-1]
                node, deps, idx = frame
                if idx >= len(deps):
                    color[node] = BLACK
                    frames.pop()
                    path.pop()
                    on_path.discard(node)
                    continue
                frame[2] += 1
                dep = deps[idx]
                if dep not in self._formulas:
                    continue
                state = color.get(dep, WHITE)
                if state == WHITE:
                    color[dep] = GRAY
                    path.append(dep)
                    on_path.add(dep)
                    frames.append([dep, self._formula_deps(dep), 0])
                elif state == GRAY and dep in on_path:
                    pos = path.index(dep)
                    for k in range(pos, len(path)):
                        cyclic.add(path[k])
            # Mark everything on this DFS tree's gray->gray back-edge cycles.
        for key in cyclic:
            cell = self._cells.get(key)
            if cell is not None:
                cell.value = "#CYCLE!"

        # Phase 2: evaluate all non-cyclic formula cells in topological order,
        # iteratively (no deep Python recursion over cells).
        evaluated: set[tuple[int, int]] = set(cyclic)
        for start in self._formulas:
            if start in evaluated:
                continue
            frames = [[start, self._formula_deps(start), 0]]
            visiting: set[tuple[int, int]] = {start}
            while frames:
                frame = frames[-1]
                node, deps, idx = frame
                if idx >= len(deps):
                    frames.pop()
                    visiting.discard(node)
                    if node not in evaluated:
                        ast = self._formulas.get(node)
                        if ast is not None:
                            self._cells[node].value = self._eval(ast)
                        evaluated.add(node)
                    continue
                frame[2] += 1
                dep = deps[idx]
                if dep not in self._formulas:
                    continue
                if dep in evaluated or dep in visiting:
                    continue
                visiting.add(dep)
                frames.append([dep, self._formula_deps(dep), 0])

    # -- expression evaluation ----------------------------------------------

    def _cell_value(self, row: int, col: int):
        cell = self._cells.get((row, col))
        if cell is None or cell.raw is None:
            return None
        if cell.is_formula:
            return cell.value
        return self._eval_literal(cell.raw)

    def _range_values(self, rng: _Range):
        r1, r2 = min(rng.r1, rng.r2), max(rng.r1, rng.r2)
        c1, c2 = min(rng.c1, rng.c2), max(rng.c1, rng.c2)
        for r in range(r1, r2 + 1):
            for c in range(c1, c2 + 1):
                yield self._cell_value(r, c)

    def _eval(self, node: _Node):
        if isinstance(node, _Num):
            return node.value
        if isinstance(node, _Str):
            return node.value
        if isinstance(node, _Bool):
            return node.value
        if isinstance(node, _Bad):
            return node.err
        if isinstance(node, _Ref):
            return self._cell_value(node.row, node.col)
        if isinstance(node, _Range):
            return "#VALUE!"  # range outside a function argument
        if isinstance(node, _Un):
            v = self._eval(node.operand)
            if _is_err(v):
                return v
            n = _to_number(v)
            if _is_err(n):
                return n
            r = -float(n) if node.op == "-" else float(n)
            if not math.isfinite(r):
                return "#VALUE!"
            return r
        if isinstance(node, _Bin):
            return self._eval_bin(node)
        if isinstance(node, _Call):
            return self._eval_call(node)
        return "#VALUE!"

    def _eval_bin(self, node: _Bin):
        op = node.op
        if op in ("=", "<>", "<", ">", "<=", ">="):
            left = self._eval(node.left)
            if _is_err(left):
                return left
            right = self._eval(node.right)
            if _is_err(right):
                return right
            cmp = _compare(left, right)
            if isinstance(cmp, str):
                return cmp
            kind, x, y = cmp
            return _cmp_apply(kind, x, y, op)
        left = self._eval(node.left)
        if _is_err(left):
            return left
        right = self._eval(node.right)
        if _is_err(right):
            return right
        if op == "&":
            return _to_text(left) + _to_text(right)
        ln = _to_number(left)
        if _is_err(ln):
            return ln
        rn = _to_number(right)
        if _is_err(rn):
            return rn
        ln = float(ln)
        rn = float(rn)
        if op == "+":
            r = ln + rn
        elif op == "-":
            r = ln - rn
        elif op == "*":
            r = ln * rn
        elif op == "/":
            if rn == 0.0:
                return "#DIV/0!"
            r = ln / rn
        elif op == "^":
            if ln == 0.0 and rn < 0:
                return "#DIV/0!"
            try:
                r = ln ** rn
            except OverflowError:
                return "#VALUE!"
            except ZeroDivisionError:
                return "#DIV/0!"
            except ValueError:
                return "#VALUE!"
            if isinstance(r, complex):
                return "#VALUE!"
        else:
            return "#VALUE!"
        if not math.isfinite(r):
            return "#VALUE!"
        return r

    def _eval_call(self, node: _Call):
        fn = _FUNCS.get(node.name)
        if fn is None:
            return "#NAME?"
        return fn(self, node.args)

    def _collect_numbers(self, args: list[_Node], count_mode: bool):
        values: list[float] = []
        for arg in args:
            if isinstance(arg, _Range):
                for v in self._range_values(arg):
                    if _is_err(v):
                        if count_mode:
                            continue
                        return ([], v)
                    if isinstance(v, bool):
                        continue
                    if isinstance(v, float):
                        values.append(v)
                continue
            v = self._eval(arg)
            if _is_err(v):
                if count_mode:
                    continue
                return ([], v)
            if isinstance(v, bool):
                values.append(1.0 if v else 0.0)
            elif isinstance(v, float):
                values.append(v)
            elif v is None:
                values.append(0.0)
            else:
                if count_mode:
                    continue
                return ([], "#VALUE!")
        return (values, None)

    def _fn_sum(self, args: list[_Node]):
        values, err = self._collect_numbers(args, count_mode=False)
        if err:
            return err
        return float(math.fsum(values))

    def _fn_average(self, args: list[_Node]):
        values, err = self._collect_numbers(args, count_mode=False)
        if err:
            return err
        if not values:
            return "#DIV/0!"
        return float(math.fsum(values) / len(values))

    def _fn_min(self, args: list[_Node]):
        values, err = self._collect_numbers(args, count_mode=False)
        if err:
            return err
        if not values:
            return 0.0
        return float(min(values))

    def _fn_max(self, args: list[_Node]):
        values, err = self._collect_numbers(args, count_mode=False)
        if err:
            return err
        if not values:
            return 0.0
        return float(max(values))

    def _fn_count(self, args: list[_Node]):
        values, _err = self._collect_numbers(args, count_mode=True)
        return float(len(values))

    def _fn_if(self, args: list[_Node]):
        if len(args) not in (2, 3):
            return "#VALUE!"
        cond = self._eval(args[0])
        if _is_err(cond):
            return cond
        if isinstance(cond, bool):
            truthy = cond
        elif isinstance(cond, float):
            truthy = cond != 0.0
        elif cond is None:
            truthy = False
        else:
            return "#VALUE!"
        if truthy:
            return self._eval(args[1])
        if len(args) == 3:
            return self._eval(args[2])
        return False

    def _fn_concat(self, args: list[_Node]):
        parts: list[str] = []
        for arg in args:
            if isinstance(arg, _Range):
                for v in self._range_values(arg):
                    if _is_err(v):
                        return v
                    parts.append(_to_text(v))
            else:
                v = self._eval(arg)
                if _is_err(v):
                    return v
                parts.append(_to_text(v))
        return "".join(parts)

    def _fn_len(self, args: list[_Node]):
        if len(args) != 1:
            return "#VALUE!"
        v = self._eval(args[0])
        if _is_err(v):
            return v
        return float(len(_to_text(v)))

    def _fn_abs(self, args: list[_Node]):
        if len(args) != 1:
            return "#VALUE!"
        v = self._eval(args[0])
        if _is_err(v):
            return v
        n = _to_number(v)
        if _is_err(n):
            return n
        return abs(float(n))

    def _fn_round(self, args: list[_Node]):
        if len(args) not in (1, 2):
            return "#VALUE!"
        v = self._eval(args[0])
        if _is_err(v):
            return v
        n = _to_number(v)
        if _is_err(n):
            return n
        digits = 0
        if len(args) == 2:
            dv = self._eval(args[1])
            if _is_err(dv):
                return dv
            dn = _to_number(dv)
            if _is_err(dn):
                return dn
            digits = int(float(dn))
        return _round_half_away(float(n), digits)


_FUNCS = {
    "SUM": Sheet._fn_sum,
    "AVERAGE": Sheet._fn_average,
    "MIN": Sheet._fn_min,
    "MAX": Sheet._fn_max,
    "COUNT": Sheet._fn_count,
    "IF": Sheet._fn_if,
    "CONCAT": Sheet._fn_concat,
    "LEN": Sheet._fn_len,
    "ABS": Sheet._fn_abs,
    "ROUND": Sheet._fn_round,
}
